<template>
  <section v-if="demo" class="prospect-admin" aria-label="Organization demo directory">
    <header><div><p class="label">ORGANIZATION DIRECTORY</p><h2>{{ demo.name }} <span class="status">{{ demo.status === 'DEMO' ? 'Demo' : 'Live' }}</span></h2><p>Manage your public pages and connect your team’s real accounts.</p></div><a :href="demo.usersUrl">Open Users →</a></header>
    <div class="public-links"><a :href="demo.providerUrl" target="_blank" rel="noopener"><strong>Provider page ↗</strong><span>{{ demo.providerUrl }}</span></a><a :href="demo.careersUrl" target="_blank" rel="noopener"><strong>Careers · Plotline ↗</strong><span>{{ demo.careersUrl }}</span></a><a :href="demo.hiringUrl"><strong>Manage jobs →</strong><span>Job descriptions and careers branding</span></a></div>
    <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="success" class="message" role="status">{{ success }}</p>
    <details :open="showEmployees"><summary>Employees · {{ demo.providers.length }} profiles <span v-if="temporaryCount">· {{ temporaryCount }} temporary accounts</span></summary>
      <p class="help">Replace temporary addresses with each employee’s real email. Their profile, client assignments and schedule stay connected. Demo status remains until the organization switches to live.</p>
      <div class="employee-list"><article v-for="person in demo.providers" :key="person.id"><div><strong>{{ person.first_name }} {{ person.last_name }}</strong><span>{{ person.credential || person.role }} · {{ person.status === 'DEMO' ? 'Demo' : person.status }}</span></div><form v-if="temporary(person.email) && demo.canManage" @submit.prevent="saveEmail(person)"><label :for="`demo-email-${person.id}`" class="sr-only">Real email for {{ person.first_name }} {{ person.last_name }}</label><input :id="`demo-email-${person.id}`" v-model="emails[person.id]" type="email" required placeholder="Employee’s real email" :disabled="busy"><button :disabled="busy">Save email</button></form><div v-else class="real-email"><span>{{ person.email }}</span><button v-if="demo.canManage && !temporary(person.email)" :disabled="busy" @click="sendLink(person)">Send password-set link</button></div></article></div>
    </details>
    <details v-if="demo.status === 'DEMO' && demo.canManage" class="cleanup"><summary>Sample data and live activation</summary><p class="help">Clear only this organization’s seeded clients, appointments, availability and example jobs. Provider profiles, office locations, branding and assigned real emails are retained.</p><p class="counts">{{ fixtureCount }} tracked sample records{{ demo.fixturesClearedAt ? ' · Sample data has been cleared' : '' }}</p><label :for="`demo-confirm-${agencyId}`">Type <strong>{{ demo.slug }}</strong> to confirm</label><input :id="`demo-confirm-${agencyId}`" v-model="confirmation" autocomplete="off"><div class="cleanup-actions"><button :disabled="busy || confirmation !== demo.slug" @click="cleanup(false)">Clear sample data</button><button :disabled="busy || confirmation !== demo.slug || temporaryCount > 0" @click="cleanup(true)">Clear samples &amp; switch to live</button></div><p v-if="temporaryCount" class="help">Assign {{ temporaryCount }} remaining real email address{{ temporaryCount===1?'':'es' }} before switching to live. Sample cleanup is available now.</p></details>
  </section>
  <p v-else-if="error && !quiet" role="alert">{{ error }}</p>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue';
import api from '../../services/api';
const props = defineProps({agencyId:[String,Number],quiet:{type:Boolean,default:true},showEmployees:{type:Boolean,default:false}});
const demo=ref(null),error=ref(''),success=ref(''),busy=ref(false),confirmation=ref(''),emails=reactive({});
const temporary = value => /@(?:[a-z0-9-]+\.)?demo\.invalid$/i.test(value || '');
const temporaryCount=computed(()=>demo.value?.providers.filter(p=>temporary(p.email)).length||0);
const fixtureCount=computed(()=>demo.value?.records.filter(r=>r.record_kind==='fixture').reduce((n,r)=>n+Number(r.count),0)||0);
let requestId=0;
async function load(){const id=++requestId;demo.value=null;if(!props.agencyId)return;try{const{data}=await api.get(`/prospect-demos/${props.agencyId}`,{skipGlobalLoading:true});if(id===requestId)demo.value=data;}catch(e){if(id===requestId&&e.response?.status!==404)error.value=e.response?.data?.error?.message||'Could not load the organization directory.';}}
async function action(fn,message){busy.value=true;error.value='';success.value='';try{await fn();await load();success.value=message;}catch(e){error.value=e.response?.data?.error?.message||e.message||'The change could not be completed.';}finally{busy.value=false;}}
const saveEmail=person=>action(()=>api.patch(`/prospect-demos/${props.agencyId}/employees/${person.id}`,{email:emails[person.id]}),'Email assigned. Send a password-set link when the employee is ready.');
async function sendLink(person){await action(async()=>{const{data}=await api.post(`/users/${person.id}/send-reset-password-link`,{sendEmail:true,forceNew:true,expiresInHours:48});if(data.emailSent===false)throw new Error('The email was not sent. Check delivery settings.');},`Password-set link sent to ${person.email}.`);}
const cleanup=activate=>action(()=>api.post(`/prospect-demos/${props.agencyId}/${activate?'activate':'clear'}`,{confirmSlug:confirmation.value}),activate?'Sample data removed. The organization is now live.':'Sample data removed. Your team, offices and branding are retained.');
watch(()=>props.agencyId,load,{immediate:true});
</script>
<style scoped>
.prospect-admin{border:1px solid #d6e1e9;border-radius:12px;padding:24px;background:#fff;color:#18324c;margin-bottom:26px;min-width:0}.prospect-admin header{display:flex;justify-content:space-between;gap:20px;align-items:center}.label{font-size:10px;font-weight:750;letter-spacing:.12em;color:#527087}.prospect-admin h2{font-size:21px;margin:8px 0}.prospect-admin header p:not(.label){font-size:13px;color:#617386;line-height:1.7}.status{font-size:11px;border-radius:4px;background:#eaf1f8;padding:5px 9px;margin-left:8px;vertical-align:middle}.public-links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.public-links a{display:grid;gap:9px;border:1px solid #dbe4eb;border-radius:8px;padding:16px;text-decoration:none;color:#18324c;min-width:0}.public-links span{font-size:11px;color:#617386;overflow-wrap:anywhere}.prospect-admin summary{cursor:pointer;font-size:14px;font-weight:650;padding:12px 0}.help,.counts{font-size:12px;line-height:1.8;color:#617386}.employee-list article{padding:15px 0;border-top:1px solid #e3e9ef;display:grid;grid-template-columns:minmax(160px,1fr) minmax(240px,1.5fr);gap:20px;align-items:center}.employee-list article>div:first-child{display:grid;gap:6px}.employee-list article span{font-size:12px;color:#617386;overflow-wrap:anywhere}.employee-list form,.real-email{display:flex;align-items:center;justify-content:space-between;gap:10px}.prospect-admin input{min-width:0;border:1px solid #bacbd9;border-radius:5px;padding:10px;font:inherit;font-size:12px}.employee-list input{flex:1;width:0}.prospect-admin button{border:1px solid #b9c9d7;background:#f6f9fc;color:#18324c;border-radius:5px;padding:10px 12px;font-size:12px;cursor:pointer}.prospect-admin button:disabled{opacity:.5;cursor:default}.cleanup{border-top:1px solid #dbe4eb;margin-top:10px}.cleanup>label{display:block;font-size:12px;margin:15px 0 8px}.cleanup-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}.message{padding:12px;border-radius:6px;background:#edf6ef;font-size:13px}.error{background:#fff0ed;color:#8c352a}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.prospect-admin a:focus-visible,.prospect-admin button:focus-visible,.prospect-admin input:focus-visible{outline:3px solid #5ea2e7;outline-offset:3px}@media(max-width:700px){.prospect-admin{padding:18px}.prospect-admin header{display:block}.public-links{grid-template-columns:1fr}.employee-list article{grid-template-columns:1fr;gap:10px}.employee-list form,.real-email{flex-wrap:wrap}.employee-list input{width:100%;min-width:170px}}
</style>
